SysDataModelXML.SQLScript:
DECLARE @DOCNUM VARCHAR(30) = '{0}';
WITH CARD_DATA AS ( -- 基本信息 SELECT ROUTYP+'/'+CASE WHEN ROUTYP='SFC' THEN MFGNUM WHEN ROUTYP='ICC' THEN LOT+'-'+TV WHEN ROUTYP='IMI' THEN DOCNUM WHEN ROUTYP='INE' THEN CONVERT(VARCHAR(16),DOCDAT,23) END AS TITLE , ITMNO AS INFO , '' OPENUM ,ISNULL(CUSCOD, '') + ISNULL(DEMANDER, '') + '/' + ISNULL(INTSPEC, '') AS REMARK , 0 AS CHECKED , 0 AS FIXED , 1.8 AS CARDSIZE , CASE WHEN STA = 1 THEN '#e57373' WHEN STA = 2 THEN '#4CAF50' WHEN STA = 0 THEN '' END AS TITLECOLOR , '#76B3E7' AS BORDERCOLOR , 1 AS SORT_ORDER FROM QAINSPH WHERE DOCNUM = @DOCNUM
UNION ALL
SELECT CAST(L.OPENUM AS VARCHAR) AS TITLE , D.RPTTTL2 INFO , L.OPENUM , D.RPTGRP2 REMARK , 0 AS CHECKED , 0 AS FIXED , 0.5 AS CARDSIZE , CASE WHEN L.STA = 1 THEN '#e57373' WHEN L.STA = 2 THEN '#4CAF50' WHEN L.STA = 0 THEN '' END AS TITLECOLOR , '#76B3E7' AS BORDERCOLOR , 10 + ROW_NUMBER() OVER ( ORDER BY L.OPENUM ) AS SORT_ORDER FROM QAINSPL L INNER JOIN QAOPESTD D ON D.OPESTD = L.OPESTD WHERE DOCNUM = @DOCNUM ) -- 最终查询 SELECT OPENUM , TITLE , INFO , REMARK , CHECKED , FIXED , CARDSIZE , TITLECOLOR , BORDERCOLOR , SORT_ORDER FROM CARD_DATA ORDER BY SORT_ORDER;
